    {
      "card_ids": ["C03"],
      "claim": "Compound 7 crossed the murine BBB with brain uptake of 5.9% ID/g in microPET PK, demonstrating robust brain penetration for an aromatic heterocycle with a fluorinated aryl group.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "QST was confirmed as a brain-penetrant molecule by equilibrium dialysis measurement of unbound brain-to-plasma concentration, and its pyrimidine-piperidine motif is directly analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 2 showed good brain exposure in mouse brain/plasma PK at 8 min, supporting rapid CNS access for a small molecule with similar aromatic and heterocyclic features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
